package com.bookstore.bike.repo; import com.bookstore.bike.entity.*; import jakarta.persistence.LockModeType; import org.springframework.data.jpa.repository.*; import org.springframework.data.repository.query.Param; import java.util.*;
public interface BikeRepository extends JpaRepository<Bike,Long>{List<Bike> findByAvailabilityAndVerificationStatus(Enums.AvailabilityStatus a,Enums.VerificationStatus v); List<Bike> findByCityContainingIgnoreCaseAndAvailabilityAndVerificationStatus(String city,Enums.AvailabilityStatus a,Enums.VerificationStatus v); List<Bike> findByOwnerIdOrderByCreatedAtDesc(Long ownerId); @Lock(LockModeType.PESSIMISTIC_WRITE) @Query("select b from Bike b where b.id=:id") Optional<Bike> lockById(@Param("id") Long id);}
